{"file_path":"/home/user/bench-runs/e13-probe-review-sonnet-t5t6-20260927T231225Z/cell-ZcQUul/src/env.js","content":"/** The environment layer: `CONF_` variables read from standard input, one per line. */

import { indent, valueColumn } from './ini.js'
import { SETTINGS } from './schema.js'

/** One refusal of an environment line, carrying the 1-based line and column it was read at. */
export class EnvError extends Error {
  /**
   * @param {number} line - the 1-based input line.
   * @param {number} column - the 1-based column of the raw line.
   * @param {string} message - the message the specification words, without the position.
   */
  constructor(line, column, message) {
    super(message)
    this.name = 'EnvError'
    this.line = line
    this.column = column
  }
}

/** The `CONF_...` variable name a schema key travels under. */
function variableName(key) {
  return `CONF_${key.toUpperCase().replace(/\./g, '_')}`
}

const BY_VARIABLE_NAME = new Map(SETTINGS.map(declared => [variableName(declared.key), declared.key]))

/**
 * Parse environment text into the settings it sets.
 * @param {string} text - the whole standard input.
 * @returns {Map<string, {text: string, line: number, column: number}>} each schema key's raw
 *   value, its line and the column of its first character (or, when empty, one past the line's
 *   last non-space character).
 * @throws {EnvError} on the first line the grammar refuses.
 */
export function parse(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  const values = new Map()
  const seenNames = new Set()
  for (const [index, raw] of lines.entries()) {
    const line = index + 1
    const trimmed = raw.trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue
    const split = trimmed.indexOf('=')
    if (split === -1) throw new EnvError(line, indent(raw), 'expected NAME=VALUE')
    const name = trimmed.slice(0, split).trim()
    if (name === '') throw new EnvError(line, indent(raw), 'expected a variable name')
    const key = BY_VARIABLE_NAME.get(name)
    if (key === undefined) throw new EnvError(line, indent(raw), `unknown environment variable ${name}`)
    if (seenNames.has(name)) throw new EnvError(line, indent(raw), `${name} is set twice`)
    seenNames.add(name)
    const column = valueColumn(raw, trimmed, split)
    values.set(key, { text: trimmed.slice(split + 1).trim(), line, column })
  }
  return values
}
"}

