/**
 * Merge named layers, later over earlier.
 * @param {readonly {name: string, values: Map<string, {text: string, [key: string]: unknown}>}[]} layers
 *   - the layers, weakest first.
 * @returns {Map<string, {text: string, layer: string, [key: string]: unknown}>} each key's winning
 *   entry, annotated with the name of the layer that set it.
 */
export function merge(layers) {
  const merged = new Map()
  for (const layer of layers) {
    for (const [key, entry] of layer.values) merged.set(key, { ...entry, layer: layer.name })
  }
  return merged
}
"}

